using Bunit;
using Microsoft.AspNetCore.Components;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Tempo.Blazor.Components.Diagram.Models;
using Tempo.Blazor.Components.Modeling;
using Tempo.Blazor.Configuration;
using Tempo.Blazor.Modeling;
using Tempo.Blazor.Modeling.BpmnXml;
using Tempo.Blazor.Tests.Localization;

namespace Tempo.Blazor.Tests.Modeling;

/// <summary>
/// Phase 3 render tests (plan 6fca9139): the coordinates imported from BPMNDI (or generated by
/// the headless auto-layout for DI-less documents) must surface unchanged in the
/// <c>TmModelingEditor</c> preview — the stored view is the layout authority.
/// </summary>
public sealed class BpmnViewRenderTests : LocalizationTestBase
{
    private const string DiProviderKey = "tempo.tests.bpmn.di";
    private const string AutoLayoutProviderKey = "tempo.tests.bpmn.autolayout";

    private readonly ModelingEditorTestClock _clock = new();

    public BpmnViewRenderTests()
    {
        Services.AddTempoBlazorModeling();
        Services.AddSingleton<TimeProvider>(_clock);
        Services.AddSingleton<IModelingModelProvider>(new ImportedBpmnModelProvider(DiProviderKey, "simple-process.bpmn"));
        Services.AddSingleton<IModelingModelProvider>(new ImportedBpmnModelProvider(AutoLayoutProviderKey, "no-bpmndi.bpmn"));
    }

    [Fact]
    public void Imported_bpmndi_coordinates_render_in_the_editor_preview()
    {
        DiagramDocument? generated = null;
        using var cut = Render<TmModelingEditor>(parameters => parameters
            .Add(p => p.ProviderKey, DiProviderKey)
            .Add(p => p.OnDiagramGenerated, EventCallback.Factory.Create<DiagramDocument>(this, document => generated = document)));

        cut.WaitForAssertion(() =>
        {
            generated.Should().NotBeNull();
            var page = generated!.Pages.Should().ContainSingle().Subject;
            var start = page.Nodes.Single(node => node.Data.GetValueOrDefault("modelElementId") as string == "StartEvent_1");
            (start.X, start.Y, start.W, start.H).Should().Be((172, 152, 36, 36));
            var task = page.Nodes.Single(node => node.Data.GetValueOrDefault("modelElementId") as string == "Task_EnterOrder");
            (task.X, task.Y).Should().Be((260, 130));
            page.Edges.Should().Contain(edge => edge.Waypoints.Count == 3,
                "the DI polyline of Flow_Rejected renders with its bends");
        });
    }

    [Fact]
    public void Auto_layouted_coordinates_render_in_the_editor_preview()
    {
        DiagramDocument? generated = null;
        using var cut = Render<TmModelingEditor>(parameters => parameters
            .Add(p => p.ProviderKey, AutoLayoutProviderKey)
            .Add(p => p.OnDiagramGenerated, EventCallback.Factory.Create<DiagramDocument>(this, document => generated = document)));

        cut.WaitForAssertion(() =>
        {
            generated.Should().NotBeNull();
            var page = generated!.Pages.Should().ContainSingle().Subject;
            page.Nodes.Should().HaveCount(8, "the DI-less process is fully laid out headlessly");

            var start = page.Nodes.Single(node => node.Data.GetValueOrDefault("modelElementId") as string == "StartEvent_NoDi");
            var end = page.Nodes.Single(node => node.Data.GetValueOrDefault("modelElementId") as string == "EndEvent_NoDi");
            end.X.Should().BeGreaterThan(start.X, "the token flow runs left to right");
        });
    }

    /// <summary>Provider serving one imported corpus model (a fresh import per request keeps the tests isolated).</summary>
    private sealed class ImportedBpmnModelProvider : IModelingModelProvider
    {
        private readonly string _fixture;

        public ImportedBpmnModelProvider(string key, string fixture)
        {
            ProviderKey = key;
            _fixture = fixture;
        }

        public string ProviderKey { get; }

        public Task<ModelingModelDto> GetModelAsync(ModelingModelRequest request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var result = new BpmnXmlImporter().Import(BpmnCorpusPaths.ReadFixture(_fixture));
            result.HasErrors.Should().BeFalse(result.ErrorMessage ?? $"import of {_fixture} failed");
            return Task.FromResult(result.Models[0]);
        }
    }
}
